import fs from 'fs';
import path from 'path';
import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from '/root/data/object.mjs';

const outputBase = '/root/output';
const partMeshesDir = path.join(outputBase, 'part_meshes');
const linksDir = path.join(outputBase, 'links');

fs.mkdirSync(partMeshesDir, { recursive: true });
fs.mkdirSync(linksDir, { recursive: true });

const root = createScene();
root.updateMatrixWorld(true);

const exporter = new OBJExporter();

// Collect groups (parts) excluding root
const parts = [];
root.traverse((obj) => {
  if (obj instanceof THREE.Group && obj !== root) {
    parts.push(obj);
  }
});

function sanitize(name) {
  return name && name.length ? name : 'unnamed';
}

function writeObj(filePath, objText) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, objText);
}

// Map mesh -> nearest parent group (part)
const meshAssignments = new Map(); // mesh -> partName
root.traverse((obj) => {
  if (obj instanceof THREE.Mesh) {
    // Find nearest ancestor group (excluding root)
    let parent = obj.parent;
    while (parent && !(parent instanceof THREE.Group && parent !== root)) {
      parent = parent.parent;
    }
    const partName = parent ? sanitize(parent.name) : 'root';
    meshAssignments.set(obj, partName);
  }
});

// Export individual meshes into part folders
for (const [mesh, partName] of meshAssignments.entries()) {
  mesh.updateWorldMatrix(true, false);
  const meshName = sanitize(mesh.name);
  const objText = exporter.parse(mesh);
  const outPath = path.join(partMeshesDir, partName, `${meshName}.obj`);
  writeObj(outPath, objText);
}

// Export each part group as a combined OBJ in links/
for (const part of parts) {
  part.updateWorldMatrix(true, true);
  const partName = sanitize(part.name);
  const objText = exporter.parse(part);
  const outPath = path.join(linksDir, `${partName}.obj`);
  writeObj(outPath, objText);
}

// Also include root as a combined link for completeness
const rootLinkPath = path.join(linksDir, `${sanitize(root.name)}.obj`);
writeObj(rootLinkPath, exporter.parse(root));

console.log(`Exported ${meshAssignments.size} meshes and ${parts.length + 1} group links.`);
